import React, { useMemo, useState } from "react";
import moduleStore from "@/store/module";
import { Button, Dropdown, Grid, Menu, Message, Modal, Space, Spin, Tooltip } from "@arco-design/web-react";
import { useObserver } from "mobx-react-lite";
import { AddModule, ItemView } from "@/components/ModuleList";
import store from "@/store";
import { IconCodeSquare, IconMoreVertical, IconSync } from "@arco-design/web-react/icon";
import { useHistory } from "react-router-dom";
import ajax from "@/utils/ajax";


const LocalModule = () => {

    const history = useHistory();

    useState(() => {
        moduleStore.getModuleList();
    })

    return useObserver(() => {

        const [visible, setVisible] = useState<boolean>(false);


        return (
            <div>
                <div className="flex justify-between bg-white pb-4 pr-4">
                    <div></div>
                    <Space>
                        <Button type="primary" onClick={() => setVisible(true)}>新增模块</Button>
                        <Tooltip content="刷新列表">
                            <Button type="primary" icon={<IconSync />}></Button>
                        </Tooltip>
                    </Space>
                </div>
                <Spin loading={moduleStore.loading} className={"w-full bg-slate-50"}>
                    <div className='p-2'>
                        <Grid.Row gutter={[16,16]} >
                            {moduleStore.list.map((o) => {

                                const dropList = (
                                    <Menu>
                                        <Menu.Item key='1'
                                            onClick={() => {
                                                Modal.confirm({
                                                    title: "提示",
                                                    content: `请确认是否上传 ${o.nickname} 模块`,
                                                    onOk: () => {
                                                        return ajax.post('/publishModule', {
                                                            id: o.uid
                                                        }).then((res) => {
                                                            Message.success(`${o.nickname} 模块上传成功`);
                                                        })
                                                    }
                                                })
                                            }}
                                        >
                                            <Tooltip content="上传（同步组件）到系统组件库">上传</Tooltip>
                                        </Menu.Item>
                                        <Menu.Item key="2"
                                            onClick={() => {
                                                Modal.confirm({
                                                    title: "提示",
                                                    content: `请确认是否删除 ${o.nickname} 模块`,
                                                    onOk: () => {
                                                        return ajax.post('/apijson/delete', {
                                                            "Module": {
                                                                id: o.uid,
                                                            }
                                                        }).then((res) => {
                                                            Message.success("删除成功");
                                                            moduleStore.getModuleList();
                                                        })
                                                    }
                                                })
                                            }}
                                        >删除</Menu.Item>
                                    </Menu>
                                )
                                
                                return (
                                    <Grid.Col span={6} key={o.key}>
                                        <ItemView
                                            key={o.key}
                                            item={o}
                                            extra={(
                                                <Space>
                                                    <Button
                                                        type="primary"
                                                        icon={<IconCodeSquare />} 
                                                        onClick={() => {
                                                            history.push(`/system/modules/save?moduleId=${o.moduleId}`)
                                                        }}
                                                    />
                                                    <Dropdown droplist={dropList} position='bl'>
                                                        <Button type='text' icon={<IconMoreVertical />} />
                                                    </Dropdown>
                                                </Space>
                                            )}
                                        />
                                    </Grid.Col>
                                )
                            })}
                        </Grid.Row>
                    </div>
                </Spin>
                <AddModule
                    visible={visible}
                    onCancel={() => setVisible(false)}
                    onSuccess={() => {
                        Message.success("创建成功");
                        moduleStore.getModuleList();
                    }}
                />
            </div>
        )
    })
}


export default LocalModule;